  'Indicatif, subjonctif, conditionnel et impératif.': { de: 'Indikativ, Subjonctif, Konditional und Imperativ.', en: 'Indicative, subjunctive, conditional and imperative.', it: 'Indicativo, congiuntivo, condizionale e imperativo.', es: 'Indicativo, subjuntivo, condicional e imperativo.' },
