  'verbes en -er, sauf aller.': { de: 'Verben auf -er, außer aller.', en: 'verbs ending in -er, except aller.', it: 'verbi in -er, tranne aller.', es: 'verbos en -er, excepto aller.' },
  'verbes en -ir faisant -issons.': { de: 'Verben auf -ir, deren nous-Form auf -issons endet.', en: 'verbs ending in -ir whose nous form ends in -issons.', it: 'verbi in -ir che alla forma nous terminano in -issons.', es: 'verbos en -ir cuya forma nous termina en -issons.' },
  'tous les autres verbes, souvent irréguliers.': { de: 'alle anderen, oft unregelmäßigen Verben.', en: 'all other verbs, which are often irregular.', it: 'tutti gli altri verbi, spesso irregolari.', es: 'todos los demás verbos, a menudo irregulares.' },
  'Être et avoir': { de: 'Être und avoir', en: 'Être and avoir', it: 'Être e avoir', es: 'Être y avoir' },
  'Ces deux verbes ont leurs propres conjugaisons et servent aussi d’auxiliaires pour former les temps composés.': { de: 'Diese beiden Verben haben eigene Konjugationen und dienen auch als Hilfsverben zur Bildung zusammengesetzter Zeiten.', en: 'These two verbs have their own conjugations and also serve as auxiliaries for compound tenses.', it: 'Questi due verbi hanno coniugazioni proprie e servono anche da ausiliari per formare i tempi composti.', es: 'Estos dos verbos tienen conjugaciones propias y también sirven de auxiliares para formar los tiempos compuestos.' },
